// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Roulette} from "../src/Roulette.sol";

contract InvMutTest is Test {
    Roulette c;
    function setUp() public { c = new Roulette(); }
    function testFuzz_property(uint8 n, uint256 blockNum) public {
        vm.assume(blockNum % 15 == 0);
        vm.assume(n <= 10);

        uint256 ts = block.timestamp + 1;
        for (uint8 i = 0; i < n; i++) {
            vm.roll(block.number + 1);
            vm.warp(ts);
            address caller = address(uint160(uint256(keccak256(abi.encode(i)))));
            vm.deal(caller, 10 ether);
            vm.prank(caller);
            (bool ok,) = address(c).call{value: 10 ether}("");
            require(ok, "prep call failed");
            ts++;
        }

        vm.roll(blockNum);
        vm.warp(ts);
        address triggerCaller = address(uint160(uint256(keccak256(abi.encode("trigger")))));
        vm.deal(triggerCaller, 10 ether);
        vm.prank(triggerCaller);
        (bool success,) = address(c).call{value: 10 ether}("");
        require(success, "trigger call failed");

        assertEq(address(c).balance, 0, "balance not zero after transfer");
    }
}
